+/**
+ * Strips unknown keys from a raw object based on Zod unrecognized_keys errors.
+ * Returns a deep clone with the unknown keys removed.
+ */
+function stripUnknownKeys(raw: unknown, errors: z.ZodError["issues"]): unknown {
+  // Collect unknown keys grouped by parent path (excluding the key name itself)
+  const keysByParentPath = new Map<string, Set<string>>();
+  for (const issue of errors) {
+    if (issue.code !== z.ZodIssueCode.unrecognized_keys) {
+      continue;
+    }
+    // The path points to the parent object; the keys are the unknown field names
+    const parentPath = issue.path;
+    const parentKey = parentPath.join(".");
+    let keys = keysByParentPath.get(parentKey);
+    if (!keys) {
+      keys = new Set<string>();
+      keysByParentPath.set(parentKey, keys);
+    }
+    for (const k of issue.keys) {
+      keys.add(k);
+    }
+  }
+
+  // Deep clone and strip
+  const strip = (obj: unknown, path: (string | number)[]): unknown => {
+    if (obj === null || typeof obj !== "object") {
+      return obj;
+    }
+
+    // Group children by their immediate key/index for batch processing
+    const childrenByKey = new Map<string | number, unknown>();
+    if (Array.isArray(obj)) {
+      for (let i = 0; i < obj.length; i++) {
+        childrenByKey.set(i, obj[i]);
+      }
+    } else {
+      for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
+        childrenByKey.set(k, v);
+      }
+    }
+
+    const result: unknown = Array.isArray(obj) ? [] : {};
+    const resultObj = result as Record<string, unknown>;
+
+    for (const [key, value] of childrenByKey) {
+      const childPath = [...path, key];
+      const childKey = childPath.join(".");
+
+      // Check if this parent has unknown keys to strip
+      const keysToStrip = keysByParentPath.get(childKey);
+
+      if (keysToStrip && !Array.isArray(obj)) {
+        // For objects: strip the unknown keys from this object itself
+        const typedObj = obj as Record<string, unknown>;
+        for (const k of Object.keys(typedObj)) {
+          if (keysToStrip.has(k)) {
+            continue; // skip unknown key
+          }
+          resultObj[k] = strip(typedObj[k], childPath);
+        }
+      } else if (keysToStrip && Array.isArray(obj)) {
+        // For arrays: the unknown keys are array indices
+        // We need to check if the current index is to be stripped
+        const idx = typeof key === "string" ? parseInt(key, 10) : key;
+        if (typeof idx === "number" && keysToStrip.has(String(idx))) {
+          // Skip this array element entirely
+          continue;
+        }
+        resultObj[key] = strip(value, childPath);
+      } else {
+        // Recurse into child
+        resultObj[key] = strip(value, childPath);
+      }
+    }
+
+    return result;
+  };
+
+  return strip(raw, []);
